package com.dnd.simulator.service;
import com.dnd.simulator.dto.ApiDtos; import com.dnd.simulator.entity.*; import com.dnd.simulator.repository.*; import com.fasterxml.jackson.databind.JsonNode; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class WorldService {
 private final WorldRepository worlds; private final AppUserRepository users; private final FactionRepository factions; private final WorldEventRepository events; private final SimulationLogRepository logs; private final Random random=new Random();
 public WorldService(WorldRepository w,AppUserRepository u,FactionRepository f,WorldEventRepository e,SimulationLogRepository l){worlds=w;users=u;factions=f;events=e;logs=l;}
 public List<World> list(String email){return worlds.findByOwnerEmailOrderByCreatedAtDesc(email);} public World get(String id,String email){return worlds.findByIdAndOwnerEmail(id,email).orElseThrow(()->new NoSuchElementException("World not found"));}
 public World create(ApiDtos.WorldRequest r,String email){return worlds.save(new World(r.name(),r.description(),users.findByEmail(email).orElseThrow()));}
 public Faction faction(String id,ApiDtos.FactionRequest r,String email){World w=get(id,email);return factions.save(fill(new Faction(r.name(),r.alignment(),r.power(),r.description(),w),r));}
 private Faction fill(Faction f,ApiDtos.FactionRequest r){f.setName(r.name());f.setAlignment(r.alignment());f.setPower(r.power());f.setWealth(r.wealth());f.setManpower(r.manpower());f.setInfluence(r.influence());f.setTerritory(r.territory());f.setImageUrl(r.imageUrl());f.setDescription(r.description());return f;}
 public Faction updateFaction(String wid,String fid,ApiDtos.FactionRequest r,String email){get(wid,email);return factions.save(fill(factions.findByIdAndWorldId(fid,wid).orElseThrow(()->new NoSuchElementException("Faction not found")),r));}
 public void deleteFaction(String wid,String fid,String email){get(wid,email);factions.delete(factions.findByIdAndWorldId(fid,wid).orElseThrow(()->new NoSuchElementException("Faction not found")));}
 public WorldEvent event(String id,ApiDtos.EventRequest r,String email){World w=get(id,email);return applyEvent(new WorldEvent(r.title(),r.type(),r.category(),r.targetFactionId(),r.details(),w),r,id);}
 private WorldEvent applyEvent(WorldEvent e,ApiDtos.EventRequest r,String worldId){e.setPowerDelta(r.powerDelta());e.setWealthDelta(r.wealthDelta());e.setManpowerDelta(r.manpowerDelta());e.setInfluenceDelta(r.influenceDelta());e.setTerritoryDelta(r.territoryDelta());if(r.targetFactionId()!=null){var f=factions.findByIdAndWorldId(r.targetFactionId(),worldId).orElseThrow(()->new NoSuchElementException("Target faction not found"));f.setPower(f.getPower()+r.powerDelta());f.setWealth(f.getWealth()+r.wealthDelta());f.setManpower(f.getManpower()+r.manpowerDelta());f.setInfluence(f.getInfluence()+r.influenceDelta());f.setTerritory(f.getTerritory()+r.territoryDelta());factions.save(f);}return events.save(e);}
 public WorldEvent updateEvent(String wid,String eid,ApiDtos.EventRequest r,String email){get(wid,email);var old=events.findByIdAndWorldId(eid,wid).orElseThrow(()->new NoSuchElementException("Event not found"));if(old.getTargetFactionId()!=null){var f=factions.findByIdAndWorldId(old.getTargetFactionId(),wid).orElse(null);if(f!=null){f.setPower(f.getPower()-old.getPowerDelta());f.setWealth(f.getWealth()-old.getWealthDelta());f.setManpower(f.getManpower()-old.getManpowerDelta());f.setInfluence(f.getInfluence()-old.getInfluenceDelta());f.setTerritory(f.getTerritory()-old.getTerritoryDelta());factions.save(f);}}old.setTitle(r.title());old.setType(r.type());old.setCategory(r.category());old.setTargetFactionId(r.targetFactionId());old.setDetails(r.details());return applyEvent(old,r,wid);}
 public void deleteEvent(String wid,String eid,String email){get(wid,email);events.delete(events.findByIdAndWorldId(eid,wid).orElseThrow(()->new NoSuchElementException("Event not found")));}
 @Transactional public Map<String,Object> simulate(String id,String email){World w=get(id,email);var fs=factions.findByWorldId(id);if(fs.isEmpty()){var msg="The realm waits for its first faction.";logs.save(new SimulationLog(msg,w));return Map.of("message",msg,"factions",fs);}var target=fs.get(random.nextInt(fs.size()));var categories=List.of("war","trade","diplomacy","disaster");var category=categories.get(random.nextInt(categories.size()));var delta=random.nextInt(21)-10;var r=new ApiDtos.EventRequest("A "+category+" reshapes the realm","RANDOM",category,target.getId(),delta,delta/2,delta,delta,delta/5,"The world moved without a player hand.");applyEvent(new WorldEvent(r.title(),r.type(),r.category(),r.targetFactionId(),r.details(),w),r,id);var msg=r.title()+" Target: "+target.getName()+".";logs.save(new SimulationLog(msg,w));return Map.of("message",msg,"factions",factions.findByWorldId(id));}
 @Transactional public World importSnapshot(JsonNode root,String email){var source=root.has("world")?root.get("world"):root;var w=create(new ApiDtos.WorldRequest(source.path("name").asText("Imported world"),source.path("description").asText("")),email);if(root.has("factions"))for(JsonNode f:root.get("factions"))faction(w.getId(),new ApiDtos.FactionRequest(f.path("name").asText("Faction"),f.path("alignment").asText(""),f.path("power").asInt(50),f.path("wealth").asInt(50),f.path("manpower").asInt(50),f.path("influence").asInt(50),f.path("territory").asInt(1),f.path("imageUrl").asText(null),f.path("description").asText("")),email);if(root.has("events"))for(JsonNode e:root.get("events"))event(w.getId(),new ApiDtos.EventRequest(e.path("title").asText("Imported event"),e.path("type").asText("IMPORTED"),e.path("category").asText("lore"),null,e.path("powerDelta").asInt(),e.path("wealthDelta").asInt(),e.path("manpowerDelta").asInt(),e.path("influenceDelta").asInt(),e.path("territoryDelta").asInt(),e.path("details").asText("")),email);return w;}
 public Map<String,Object> data(String id,String email){get(id,email);return Map.of("factions",factions.findByWorldId(id),"events",events.findByWorldIdOrderByOccurredAtDesc(id),"logs",logs.findTop100ByWorldIdOrderByCreatedAtDesc(id));}
}
